//! D3D11 compute engine for Erika's super-resolution networks.
//!
//! Executes any [`SrModel`] with the kernels generated by
//! [`crate::renderer::sr::hlsl`]: one dispatch per layer and output-channel
//! block, inputs staged in `groupshared` memory, weights as constant-buffer
//! FMA operands, epilogues and the depth-to-space head fused, and the exact
//! border-ring passes of algebraically folded layers. Frames larger than the
//! memory budget are processed in tiles with the network's receptive-field
//! halo.
//!
//! Kernels are compiled with FXC on a background thread and cached on disk,
//! so switching models never stalls the render thread; until they are ready
//! the renderer keeps native sampling and reports `Building`. The output is a
//! `(2w)x(2h)` `R16_FLOAT` luma texture sampled like a regular luma plane.

use std::collections::HashMap;
use std::ffi::c_void;
use std::mem;
use std::path::PathBuf;
use std::sync::Arc;
use std::sync::mpsc::{Receiver, TryRecvError, channel};
use std::time::{Duration, Instant};

use ::windows::Win32::Graphics::Direct3D::Fxc::{D3DCOMPILE_OPTIMIZATION_LEVEL3, D3DCompile};
use ::windows::Win32::Graphics::Direct3D::{D3D_FEATURE_LEVEL_11_0, ID3DBlob};
use ::windows::Win32::Graphics::Direct3D11::{
    D3D11_BIND_CONSTANT_BUFFER, D3D11_BIND_SHADER_RESOURCE, D3D11_BIND_UNORDERED_ACCESS,
    D3D11_BUFFER_DESC, D3D11_FEATURE_D3D11_OPTIONS, D3D11_FEATURE_DATA_D3D11_OPTIONS,
    D3D11_QUERY_DATA_TIMESTAMP_DISJOINT, D3D11_QUERY_DESC, D3D11_QUERY_TIMESTAMP,
    D3D11_QUERY_TIMESTAMP_DISJOINT, D3D11_SUBRESOURCE_DATA, D3D11_TEXTURE2D_DESC,
    D3D11_USAGE_DEFAULT, D3D11_USAGE_IMMUTABLE, ID3D11Asynchronous, ID3D11Buffer,
    ID3D11ComputeShader, ID3D11Device, ID3D11DeviceContext, ID3D11DeviceContext1, ID3D11Query,
    ID3D11Resource, ID3D11ShaderResourceView, ID3D11Texture2D, ID3D11UnorderedAccessView,
};
use ::windows::Win32::Graphics::Dxgi::Common::{
    DXGI_FORMAT, DXGI_FORMAT_R16_FLOAT, DXGI_FORMAT_R16G16B16A16_FLOAT, DXGI_SAMPLE_DESC,
};
use ::windows::Win32::Graphics::Dxgi::IDXGIDevice;
use ::windows::core::{Interface, PCSTR};

use crate::core::{LumaUpscalerBackendStatus, PlayerError, Result};
use crate::renderer::artcnn::FrameTokenCache;
use crate::renderer::pipeline::{LumaUpscalerMode, UpscalerFamily};
use crate::renderer::sr::catalog::execution_model;
#[cfg(test)]
use crate::renderer::sr::hlsl::plan;
use crate::renderer::sr::hlsl::{D3d11Plan, RING_GROUP, plan_for_adapter, ring_pixels};
use crate::renderer::sr::model::SrModel;
use crate::renderer::sr::reference::{LumaRange, input_normalization};

/// Intermediate tensors are tiled so their textures stay under this size.
const TENSOR_BUDGET_BYTES: usize = 192 * 1024 * 1024;
/// Smallest tile edge worth the halo overhead.
const MIN_TILE: u32 = 128;
/// Bytes per parameter block when constant-buffer offsetting is available
/// (offsets are in units of 16 constants = 256 bytes).
const PARAMS_STRIDE: usize = 256;
const SHADER_CACHE_VERSION: &str = "erika-sr-d3d11-v1";
const QUERY_RING: usize = 4;
/// SRV slots cleared between dispatches (luma + sources + residual + ring
/// weights).
const SRV_SLOTS: usize = 16;
/// `Buffer<float4> Wr : register(t15)` of ring kernels.
const RING_WEIGHTS_SLOT: usize = 15;

#[repr(C)]
#[derive(Clone, Copy, Debug, Default)]
struct DispatchParams {
    region: [i32; 4],
    tile: [i32; 4],
    image: [i32; 4],
    range: [f32; 4],
    misc: [u32; 4],
}

#[derive(Clone, Copy, Debug)]
struct DispatchRecord {
    kernel: usize,
    /// Runs the kernel's ring pass instead of the tiled pass.
    ring: bool,
    params: DispatchParams,
    groups: (u32, u32),
}

struct CompiledKernel {
    shader: ID3D11ComputeShader,
    constants: ID3D11Buffer,
    /// Ring shader and its nine-variant weight buffer view.
    ring: Option<(ID3D11ComputeShader, ID3D11ShaderResourceView)>,
    /// Constants bound from the weight buffers (a multiple of 16).
    constant_count: u32,
    head_constants: Option<ID3D11Buffer>,
}

struct Network {
    model: Arc<SrModel>,
    plan: D3d11Plan,
    kernels: Vec<CompiledKernel>,
}

struct Pool {
    width: u32,
    height: u32,
    tiles: Vec<(u32, u32, u32, u32)>,
    tile_extent: (u32, u32),
    slots: Vec<(
        ID3D11Texture2D,
        ID3D11ShaderResourceView,
        ID3D11UnorderedAccessView,
    )>,
    output: (
        ID3D11Texture2D,
        ID3D11ShaderResourceView,
        ID3D11UnorderedAccessView,
    ),
    params: ID3D11Buffer,
    params_capacity: usize,
    frame_cache: FrameTokenCache,
    range: Option<LumaRange>,
    partials: Vec<(
        ID3D11Texture2D,
        ID3D11ShaderResourceView,
        ID3D11UnorderedAccessView,
    )>,
    partial_bytes: usize,
}

/// Result of a background compilation.
type CompileResult = std::result::Result<(Arc<SrModel>, D3d11Plan, Vec<Vec<u8>>), String>;

struct QuerySet {
    disjoint: ID3D11Query,
    start: ID3D11Query,
    end: ID3D11Query,
    pending: bool,
}

/// Upscaled luma produced by [`D3d11SrEngine::encode`].
pub(crate) struct UpscaledLuma {
    pub(crate) view: ID3D11ShaderResourceView,
    /// Size of `view`; presentation samples it with normalized coordinates.
    #[cfg_attr(not(test), allow(dead_code))]
    pub(crate) width: u32,
    #[cfg_attr(not(test), allow(dead_code))]
    pub(crate) height: u32,
}

#[derive(Default)]
pub(crate) struct D3d11SrEngine {
    mode: LumaUpscalerMode,
    custom: Option<Arc<SrModel>>,
    status: LumaUpscalerBackendStatus,
    network: Option<Network>,
    pending: Option<Receiver<CompileResult>>,
    pool: Option<Pool>,
    offsetting: bool,
    queries: Vec<QuerySet>,
    query_cursor: usize,
    fallback_count: u64,
    upscaled_frames: u64,
    last_encode_duration: Duration,
    last_gpu_duration: Duration,
    last_failure: Option<String>,
    /// Overrides [`TENSOR_BUDGET_BYTES`] (tests force tiling with it).
    tensor_budget: Option<usize>,
    /// Bound submission batches on Intel's driver for wide graphs.
    flush_layers: bool,
}

impl D3d11SrEngine {
    pub(crate) fn status(&self) -> LumaUpscalerBackendStatus {
        self.status
    }

    /// The network currently ready to run.
    pub(crate) fn active_model(&self) -> Option<Arc<SrModel>> {
        self.network.as_ref().map(|network| network.model.clone())
    }

    pub(crate) fn is_active(&self) -> bool {
        self.status == LumaUpscalerBackendStatus::Scalar && self.network.is_some()
    }

    pub(crate) fn fallback_count(&self) -> u64 {
        self.fallback_count
    }

    pub(crate) fn upscaled_frames(&self) -> u64 {
        self.upscaled_frames
    }

    pub(crate) fn last_encode_duration(&self) -> Duration {
        self.last_encode_duration
    }

    pub(crate) fn last_gpu_duration(&self) -> Duration {
        self.last_gpu_duration
    }

    pub(crate) fn last_failure(&self) -> Option<&str> {
        self.last_failure.as_deref()
    }

    pub(crate) fn allocated_bytes(&self) -> u64 {
        self.pool.as_ref().map_or(0, |pool| {
            let slots: u64 = self.network.as_ref().map_or(0, |network| {
                network.plan.slot_slices.iter().sum::<usize>() as u64
            }) * u64::from(pool.tile_extent.0)
                * u64::from(pool.tile_extent.1)
                * 8;
            // Output is R16F at twice the size in both dimensions.
            slots
                + u64::from(pool.width) * u64::from(pool.height) * 8
                + u64::from(pool.tile_extent.0)
                    * u64::from(pool.tile_extent.1)
                    * pool.partial_bytes as u64
        })
    }

    /// Drops resources of a previous device and rebuilds the selected model.
    pub(crate) fn attach_device(
        &mut self,
        device: &ID3D11Device,
        mode: LumaUpscalerMode,
    ) -> Result<()> {
        self.network = None;
        self.pool = None;
        self.pending = None;
        self.queries.clear();
        self.mode = LumaUpscalerMode::Off;
        self.status = LumaUpscalerBackendStatus::Off;
        self.set_mode(device, mode)
    }

    /// Keeps a custom model until a device is attached.
    pub(crate) fn store_custom_model(&mut self, model: Option<Arc<SrModel>>) {
        self.custom = model;
    }

    pub(crate) fn set_custom_model(&mut self, device: &ID3D11Device, model: Option<Arc<SrModel>>) {
        self.custom = model;
        if self.mode == LumaUpscalerMode::Custom {
            self.mode = LumaUpscalerMode::Off;
            let _ = self.set_mode(device, LumaUpscalerMode::Custom);
        }
    }

    /// Starts building `mode` in the background. Returns an error only for
    /// modes this engine cannot run at all.
    pub(crate) fn set_mode(&mut self, device: &ID3D11Device, mode: LumaUpscalerMode) -> Result<()> {
        if self.mode == mode
            && (mode == LumaUpscalerMode::Off || self.network.is_some() || self.pending.is_some())
        {
            return Ok(());
        }
        self.mode = mode;
        self.network = None;
        self.pool = None;
        self.pending = None;
        self.last_failure = None;
        if mode == LumaUpscalerMode::Off {
            self.status = LumaUpscalerBackendStatus::Off;
            return Ok(());
        }
        if mode.family() != UpscalerFamily::Network {
            self.status = LumaUpscalerBackendStatus::Inactive;
            return Err(PlayerError::Renderer(format!(
                "d3d11 network engine does not run {}",
                mode.label()
            )));
        }
        if unsafe { device.GetFeatureLevel() }.0 < D3D_FEATURE_LEVEL_11_0.0 {
            return self.fail(PlayerError::Renderer(
                "d3d11 super resolution requires Direct3D feature level 11.0".to_string(),
            ));
        }
        let model = if mode == LumaUpscalerMode::Custom {
            match self.custom.clone() {
                Some(model) => model,
                None => {
                    return self.fail(PlayerError::Renderer(
                        "custom upscaler mode selected without a loaded model".to_string(),
                    ));
                }
            }
        } else {
            match execution_model(mode) {
                Ok(model) => model,
                Err(error) => return self.fail(error),
            }
        };
        self.offsetting = constant_buffer_offsetting(device);
        let intel = unsafe {
            device
                .cast::<IDXGIDevice>()
                .and_then(|d| d.GetAdapter())
                .and_then(|a| a.GetDesc())
                .is_ok_and(|desc| desc.VendorId == 0x8086)
        };
        self.flush_layers = std::env::var("ERIKA_SR_FLUSH_LAYER")
            .ok()
            .map(|value| value == "1")
            .unwrap_or_else(|| intel && model.tensors.iter().any(|&channels| channels >= 64));
        self.status = LumaUpscalerBackendStatus::Building;
        let (sender, receiver) = channel();
        std::thread::Builder::new()
            .name("erika-sr-compile".to_string())
            .spawn(move || {
                let plan = plan_for_adapter(&model, intel);
                let _ = sender.send(compile_plan(&plan).map(|blobs| (model, plan, blobs)));
            })
            .map_err(|error| {
                PlayerError::Renderer(format!("cannot spawn SR compile thread: {error}"))
            })?;
        self.pending = Some(receiver);
        Ok(())
    }

    /// Finishes a background build if it completed. Cheap when idle.
    pub(crate) fn poll(&mut self, device: &ID3D11Device) {
        let Some(receiver) = self.pending.as_ref() else {
            return;
        };
        let result = match receiver.try_recv() {
            Ok(result) => result,
            Err(TryRecvError::Empty) => return,
            Err(TryRecvError::Disconnected) => Err("SR compile thread exited".to_string()),
        };
        self.pending = None;
        match result.and_then(|(model, plan, blobs)| {
            create_network(device, model, plan, &blobs).map_err(|error| error.to_string())
        }) {
            Ok(network) => {
                self.network = Some(network);
                self.status = LumaUpscalerBackendStatus::Scalar;
            }
            Err(error) => {
                let _ = self.fail::<()>(PlayerError::Renderer(error));
            }
        }
    }

    /// Runs the network on `luma` (a Texture2DArray SRV of the luma plane)
    /// and returns the 2x luma, or `None` while building / inactive.
    pub(crate) fn encode(
        &mut self,
        device: &ID3D11Device,
        context: &ID3D11DeviceContext,
        luma: &ID3D11ShaderResourceView,
        width: u32,
        height: u32,
        range: LumaRange,
        frame_token: Option<u64>,
    ) -> Result<Option<UpscaledLuma>> {
        self.last_encode_duration = Duration::ZERO;
        self.poll(device);
        self.collect_timing(context);
        let Some(network) = self.network.as_ref() else {
            return Ok(None);
        };
        if width < 2 || height < 2 {
            return Ok(None);
        }
        let output_size = (width * 2, height * 2);
        if let Some(pool) = self.pool.as_ref() {
            if pool.width == width
                && pool.height == height
                && pool.range == Some(range)
                && pool.frame_cache.matches(frame_token)
            {
                return Ok(Some(UpscaledLuma {
                    view: pool.output.1.clone(),
                    width: output_size.0,
                    height: output_size.1,
                }));
            }
        }
        let started = Instant::now();
        if self
            .pool
            .as_ref()
            .is_none_or(|pool| pool.width != width || pool.height != height)
        {
            let default_budget = network
                .plan
                .tile_budget_bytes
                .unwrap_or(TENSOR_BUDGET_BYTES);
            let budget = self.tensor_budget.unwrap_or_else(|| {
                std::env::var("ERIKA_SR_TILE_BUDGET_MB")
                    .ok()
                    .and_then(|value| value.parse::<usize>().ok())
                    .map_or(default_budget, |megabytes| megabytes.max(1) << 20)
            });
            self.pool = Some(Pool::build(device, &network.plan, width, height, budget)?);
        }
        let records = build_records(network, self.pool.as_ref().expect("pool built"), range);
        let pool = self.pool.as_mut().expect("pool built");
        if pool.params_capacity < records.len() {
            pool.params = create_params_buffer(device, records.len(), self.offsetting)?;
            pool.params_capacity = records.len();
        }

        let context1: Option<ID3D11DeviceContext1> = if self.offsetting {
            context.cast().ok()
        } else {
            None
        };
        if context1.is_some() {
            let mut bytes = vec![0u8; records.len() * PARAMS_STRIDE];
            for (index, record) in records.iter().enumerate() {
                let source = unsafe {
                    std::slice::from_raw_parts(
                        (&record.params as *const DispatchParams).cast::<u8>(),
                        mem::size_of::<DispatchParams>(),
                    )
                };
                bytes[index * PARAMS_STRIDE..index * PARAMS_STRIDE + source.len()]
                    .copy_from_slice(source);
            }
            unsafe {
                context.UpdateSubresource(
                    &pool.params,
                    0,
                    None,
                    bytes.as_ptr().cast::<c_void>(),
                    0,
                    0,
                );
            }
        }

        if self.queries.is_empty() {
            self.queries = create_query_ring(device);
        }
        let query = self.queries.get(self.query_cursor % QUERY_RING.max(1));
        if let Some(query) = query.filter(|query| !query.pending) {
            unsafe {
                context.Begin(&query.disjoint);
                context.End(&query.start);
            }
        }

        let network = self.network.as_ref().expect("network checked");
        let pool = self.pool.as_ref().expect("pool built");
        // ERIKA_SR_PROFILE=1: timestamp every dispatch and print per-kernel
        // GPU time (blocks on the GPU; diagnostics only).
        let profile = std::env::var_os("ERIKA_SR_PROFILE").is_some();
        let flush_layers = self.flush_layers;
        // Allocate before recording: CreateQuery between dispatches can starve
        // the GPU and makes the apparent dependency gaps meaningless.
        let stamps: Vec<(ID3D11Query, ID3D11Query)> = if profile {
            let make = || {
                let desc = D3D11_QUERY_DESC {
                    Query: D3D11_QUERY_TIMESTAMP,
                    MiscFlags: 0,
                };
                let mut query = None;
                unsafe { device.CreateQuery(&desc, Some(&mut query)) }.ok()?;
                query
            };
            records
                .iter()
                .filter_map(|_| Some((make()?, make()?)))
                .collect()
        } else {
            Vec::new()
        };
        let profile_disjoint = profile
            .then(|| create_query_ring(device))
            .and_then(|mut ring| ring.pop());
        if let Some(set) = profile_disjoint.as_ref() {
            unsafe {
                context.Begin(&set.disjoint);
                context.End(&set.start);
            }
        }
        unsafe {
            let mut current_shader: Option<(usize, bool)> = None;
            for (index, record) in records.iter().enumerate() {
                let kernel = &network.kernels[record.kernel];
                let spec = &network.plan.kernels[record.kernel];
                let ring = record
                    .ring
                    .then(|| kernel.ring.as_ref().expect("ring record has a ring kernel"));
                if current_shader != Some((record.kernel, record.ring)) {
                    match ring {
                        Some((shader, _)) => context.CSSetShader(shader, None),
                        None => context.CSSetShader(&kernel.shader, None),
                    }
                    current_shader = Some((record.kernel, record.ring));
                }
                if let Some(context1) = context1.as_ref() {
                    let first = [(index * PARAMS_STRIDE / 16) as u32, 0];
                    let count = [16u32, kernel.constant_count];
                    context1.CSSetConstantBuffers1(
                        0,
                        2,
                        Some([Some(pool.params.clone()), Some(kernel.constants.clone())].as_ptr()),
                        Some(first.as_ptr()),
                        Some(count.as_ptr()),
                    );
                } else {
                    context.UpdateSubresource(
                        &pool.params,
                        0,
                        None,
                        (&record.params as *const DispatchParams).cast::<c_void>(),
                        0,
                        0,
                    );
                    context.CSSetConstantBuffers(
                        0,
                        Some(&[Some(pool.params.clone()), Some(kernel.constants.clone())]),
                    );
                }
                if kernel.head_constants.is_some() {
                    context.CSSetConstantBuffers(2, Some(&[kernel.head_constants.clone()]));
                }
                // Unbind first so a slot never sits on SRV and UAV at once.
                context.CSSetUnorderedAccessViews(0, 3, Some([None, None, None].as_ptr()), None);
                let mut views: Vec<Option<ID3D11ShaderResourceView>> = vec![Some(luma.clone())];
                for source in &spec.sources {
                    views.push(if source.tensor == 0 {
                        None
                    } else {
                        pool.slot_view(&network.plan, source.tensor)
                    });
                }
                if let Some(residual) = spec.residual {
                    views.push(pool.slot_view(&network.plan, residual));
                }
                views.resize(SRV_SLOTS, None);
                views[RING_WEIGHTS_SLOT] = ring.map(|(_, weights)| weights.clone());
                if let Some(dense) = spec.dense.as_ref().filter(|dense| dense.step > 0) {
                    views[14] = Some(pool.partials[(dense.step - 1) % 2].1.clone());
                }
                if let Some(part) = spec.partial_head.as_ref().filter(|part| part.step > 0) {
                    views[14] = Some(pool.partials[(part.step - 1) % 2].1.clone());
                }
                context.CSSetShaderResources(0, Some(&views));
                let mut uavs = if let Some(part) = &spec.partial_head {
                    [
                        None,
                        part.last.then(|| pool.output.2.clone()),
                        (!part.last).then(|| pool.partials[part.step % 2].2.clone()),
                    ]
                } else if spec.head {
                    [None, Some(pool.output.2.clone()), None]
                } else {
                    let slot = network.plan.tensor_slot[network.model.layers[spec.layer].output]
                        .expect("non-head layer has a slot");
                    [Some(pool.slots[slot].2.clone()), None, None]
                };
                if let Some(dense) = spec.dense.as_ref().filter(|dense| !dense.last) {
                    uavs[2] = Some(pool.partials[dense.step % 2].2.clone());
                }
                context.CSSetUnorderedAccessViews(0, 3, Some(uavs.as_ptr()), None);
                if let Some(stamp) = stamps.get(index) {
                    context.End(&stamp.0);
                }
                context.Dispatch(record.groups.0, record.groups.1, 1);
                if let Some(stamp) = stamps.get(index) {
                    context.End(&stamp.1);
                }
                if flush_layers
                    && records.get(index + 1).is_none_or(|next| {
                        network.plan.kernels[next.kernel].layer != spec.layer
                            || next.params.tile != record.params.tile
                    })
                {
                    context.Flush();
                }
            }
            context.CSSetUnorderedAccessViews(0, 3, Some([None, None, None].as_ptr()), None);
            context.CSSetShaderResources(0, Some(&[const { None }; SRV_SLOTS]));
            context.CSSetConstantBuffers(0, Some(&[None, None, None]));
            context.CSSetShader(None, None);
        }

        if let Some(set) = profile_disjoint {
            unsafe {
                context.End(&set.end);
            }
            print_profile(context, network, pool, &set, &records, &stamps);
        }
        if let Some(query) = self.queries.get_mut(self.query_cursor % QUERY_RING.max(1)) {
            if !query.pending {
                unsafe {
                    context.End(&query.end);
                    context.End(&query.disjoint);
                }
                query.pending = true;
                self.query_cursor += 1;
            }
        }

        let pool = self.pool.as_mut().expect("pool built");
        pool.frame_cache.commit(frame_token);
        pool.range = Some(range);
        self.upscaled_frames = self.upscaled_frames.saturating_add(1);
        self.last_encode_duration = started.elapsed();
        Ok(Some(UpscaledLuma {
            view: pool.output.1.clone(),
            width: output_size.0,
            height: output_size.1,
        }))
    }

    pub(crate) fn record_runtime_failure(&mut self, error: &PlayerError) {
        self.status = LumaUpscalerBackendStatus::Inactive;
        self.network = None;
        self.pool = None;
        self.pending = None;
        self.last_failure = Some(error.to_string());
        self.fallback_count = self.fallback_count.saturating_add(1);
    }

    fn fail<T>(&mut self, error: PlayerError) -> Result<T> {
        self.record_runtime_failure(&error);
        Err(error)
    }

    /// Reads finished timestamp queries without stalling.
    fn collect_timing(&mut self, context: &ID3D11DeviceContext) {
        for query in &mut self.queries {
            if !query.pending {
                continue;
            }
            let Some(disjoint) = read_query::<D3D11_QUERY_DATA_TIMESTAMP_DISJOINT>(
                context,
                &query.disjoint,
                |data| data.Frequency != 0,
            ) else {
                continue;
            };
            let (Some(start), Some(end)) = (
                read_query::<u64>(context, &query.start, |value| *value != 0),
                read_query::<u64>(context, &query.end, |value| *value != 0),
            ) else {
                continue;
            };
            query.pending = false;
            if !disjoint.Disjoint.as_bool() && end > start {
                self.last_gpu_duration =
                    Duration::from_secs_f64((end - start) as f64 / disjoint.Frequency as f64);
            }
        }
    }
}

impl Pool {
    fn build(
        device: &ID3D11Device,
        plan: &D3d11Plan,
        width: u32,
        height: u32,
        budget: usize,
    ) -> Result<Self> {
        let halo = plan.max_halo as u32;
        use ::windows::Win32::Graphics::Dxgi::Common::DXGI_FORMAT_R32G32B32A32_FLOAT;
        let feature_bytes = 8;
        let sum_fp16 = std::env::var("ERIKA_SR_HEAD_FP16").ok().map_or_else(
            || plan.kernels.iter().any(|kernel| kernel.dense.is_some()),
            |value| value == "1",
        );
        let partial_bytes = if plan
            .kernels
            .iter()
            .any(|kernel| kernel.dense.is_some() || kernel.partial_head.is_some())
        {
            if sum_fp16 { 16 } else { 32 }
        } else {
            0
        };
        let bytes_per_pixel =
            plan.slot_slices.iter().sum::<usize>().max(1) * feature_bytes + partial_bytes;
        let (tiles_x, tiles_y) = tile_grid(width, height, halo, bytes_per_pixel, budget);
        let tile_w = width.div_ceil(tiles_x);
        let tile_h = height.div_ceil(tiles_y);
        let mut tiles = Vec::new();
        for ty in 0..tiles_y {
            for tx in 0..tiles_x {
                let x = tx * tile_w;
                let y = ty * tile_h;
                if x < width && y < height {
                    tiles.push((x, y, tile_w.min(width - x), tile_h.min(height - y)));
                }
            }
        }
        let extent = (tile_w + 2 * halo, tile_h + 2 * halo);
        let slots = plan
            .slot_slices
            .iter()
            .map(|&slices| {
                create_texture(
                    device,
                    extent.0,
                    extent.1,
                    slices as u32,
                    DXGI_FORMAT_R16G16B16A16_FLOAT,
                )
            })
            .collect::<Result<Vec<_>>>()?;
        let output = create_texture(device, width * 2, height * 2, 0, DXGI_FORMAT_R16_FLOAT)?;
        let partials = if plan
            .kernels
            .iter()
            .any(|kernel| kernel.dense.is_some() || kernel.partial_head.is_some())
        {
            let format = if sum_fp16 {
                DXGI_FORMAT_R16G16B16A16_FLOAT
            } else {
                DXGI_FORMAT_R32G32B32A32_FLOAT
            };
            (0..2)
                .map(|_| create_texture(device, extent.0, extent.1, 0, format))
                .collect::<Result<Vec<_>>>()?
        } else {
            Vec::new()
        };
        Ok(Self {
            width,
            height,
            tiles,
            tile_extent: extent,
            slots,
            output,
            params: create_params_buffer(device, 1, false)?,
            params_capacity: 0,
            frame_cache: FrameTokenCache::default(),
            range: None,
            partials,
            partial_bytes,
        })
    }

    fn slot_view(&self, plan: &D3d11Plan, tensor: usize) -> Option<ID3D11ShaderResourceView> {
        plan.tensor_slot[tensor].map(|slot| self.slots[slot].1.clone())
    }
}

fn budget_floor(budget: usize) -> u32 {
    // Small test budgets may split below MIN_TILE.
    if budget < TENSOR_BUDGET_BYTES / 16 {
        16
    } else {
        MIN_TILE
    }
}

/// Smallest tile grid whose tensor textures fit the budget: split the longer
/// tile edge until the halo-padded tensors fit.
fn tile_grid(
    width: u32,
    height: u32,
    halo: u32,
    bytes_per_pixel: usize,
    budget: usize,
) -> (u32, u32) {
    let fits = |tx: u32, ty: u32| {
        let w = (width.div_ceil(tx) + 2 * halo) as usize;
        let h = (height.div_ceil(ty) + 2 * halo) as usize;
        w * h * bytes_per_pixel <= budget
    };
    let (mut tx, mut ty) = (1u32, 1u32);
    while !fits(tx, ty) {
        let tile_w = width.div_ceil(tx);
        let tile_h = height.div_ceil(ty);
        if tile_w.max(tile_h) <= MIN_TILE.min(budget_floor(budget)) {
            break;
        }
        if tile_w >= tile_h {
            tx += 1;
        } else {
            ty += 1;
        }
    }
    (tx, ty)
}

fn build_records(network: &Network, pool: &Pool, range: LumaRange) -> Vec<DispatchRecord> {
    let plan = &network.plan;
    let model = &network.model;
    let (offset, scale) = input_normalization(model, range);
    let width = pool.width as i32;
    let height = pool.height as i32;
    let halo = plan.max_halo as i32;
    let mut records = Vec::new();
    for &(tx, ty, tw, th) in &pool.tiles {
        let tile_origin = [tx as i32 - halo, ty as i32 - halo];
        for (kernel_index, kernel) in plan.kernels.iter().enumerate() {
            let layer = &model.layers[kernel.layer];
            let h = plan.halos[layer.output] as i32;
            let x0 = (tx as i32 - h).max(0);
            let y0 = (ty as i32 - h).max(0);
            let x1 = (tx as i32 + tw as i32 + h).min(width);
            let y1 = (ty as i32 + th as i32 + h).min(height);
            if x1 <= x0 || y1 <= y0 {
                continue;
            }
            let params = DispatchParams {
                region: [x0, y0, x1 - x0, y1 - y0],
                tile: [tile_origin[0], tile_origin[1], 0, 0],
                image: [width, height, 0, 0],
                range: [offset, scale, 1.0 / scale, 0.0],
                misc: [
                    (kernel.out_start / 4) as u32,
                    0,
                    kernel
                        .partial_head
                        .as_ref()
                        .map_or(0, |part| part.first_slice as u32),
                    0,
                ],
            };
            let block = kernel.shape.block();
            records.push(DispatchRecord {
                kernel: kernel_index,
                ring: false,
                params,
                groups: (
                    ((x1 - x0) as u32).div_ceil(block.0),
                    ((y1 - y0) as u32).div_ceil(block.1),
                ),
            });
            // Re-evaluate the one-pixel image ring with exact weights when
            // this tile's region touches the image border.
            let touches_border = x0 == 0 || y0 == 0 || x1 == width || y1 == height;
            if kernel.ring.is_some() && touches_border {
                records.push(DispatchRecord {
                    kernel: kernel_index,
                    ring: true,
                    params,
                    groups: (ring_pixels(pool.width, pool.height).div_ceil(RING_GROUP), 1),
                });
            }
        }
    }
    records
}

fn create_network(
    device: &ID3D11Device,
    model: Arc<SrModel>,
    plan: D3d11Plan,
    blobs: &[Vec<u8>],
) -> Result<Network> {
    let mut shaders: HashMap<Vec<u8>, ID3D11ComputeShader> = HashMap::new();
    let mut shader_for = |blob: &Vec<u8>, what: usize| -> Result<ID3D11ComputeShader> {
        if let Some(shader) = shaders.get(blob) {
            return Ok(shader.clone());
        }
        let mut shader = None;
        unsafe {
            device
                .CreateComputeShader(blob, None, Some(&mut shader))
                .map_err(|error| {
                    PlayerError::Renderer(format!(
                        "d3d11 CreateComputeShader(SR layer {what}) failed: {error}"
                    ))
                })?;
        }
        let shader = shader.ok_or_else(|| {
            PlayerError::Renderer("d3d11 CreateComputeShader returned null".to_string())
        })?;
        shaders.insert(blob.clone(), shader.clone());
        Ok(shader)
    };
    let mut ring_blobs = blobs[plan.kernels.len()..].iter();
    let mut kernels = Vec::with_capacity(plan.kernels.len());
    for (spec, blob) in plan.kernels.iter().zip(blobs) {
        let shader = shader_for(blob, spec.layer)?;
        let ring = match spec.ring.as_ref() {
            Some(ring) => {
                let blob = ring_blobs.next().expect("one blob per ring kernel");
                Some((
                    shader_for(blob, spec.layer)?,
                    create_weight_buffer(device, &ring.weights)?,
                ))
            }
            None => None,
        };
        kernels.push(CompiledKernel {
            shader,
            constant_count: (spec.constants.len().max(1).div_ceil(16) * 16) as u32,
            constants: create_constants(device, &spec.constants)?,
            ring,
            head_constants: spec
                .dense
                .as_ref()
                .map(|dense| create_constants(device, &dense.constants))
                .transpose()?,
        });
    }
    Ok(Network {
        model,
        plan,
        kernels,
    })
}

/// Immutable `Buffer<float4>` holding ring-kernel weights.
fn create_weight_buffer(
    device: &ID3D11Device,
    weights: &[[f32; 4]],
) -> Result<ID3D11ShaderResourceView> {
    use ::windows::Win32::Graphics::Direct3D::D3D_SRV_DIMENSION_BUFFER;
    use ::windows::Win32::Graphics::Direct3D11::{
        D3D11_BUFFER_SRV, D3D11_BUFFER_SRV_0, D3D11_BUFFER_SRV_1, D3D11_SHADER_RESOURCE_VIEW_DESC,
        D3D11_SHADER_RESOURCE_VIEW_DESC_0,
    };
    use ::windows::Win32::Graphics::Dxgi::Common::DXGI_FORMAT_R32G32B32A32_FLOAT;
    let desc = D3D11_BUFFER_DESC {
        ByteWidth: (weights.len().max(1) * 16) as u32,
        Usage: D3D11_USAGE_IMMUTABLE,
        BindFlags: D3D11_BIND_SHADER_RESOURCE.0 as u32,
        CPUAccessFlags: 0,
        MiscFlags: 0,
        StructureByteStride: 0,
    };
    let data = D3D11_SUBRESOURCE_DATA {
        pSysMem: weights.as_ptr().cast::<c_void>(),
        SysMemPitch: 0,
        SysMemSlicePitch: 0,
    };
    let mut buffer = None;
    unsafe {
        device
            .CreateBuffer(&desc, Some(&data), Some(&mut buffer))
            .map_err(|error| {
                PlayerError::Renderer(format!(
                    "d3d11 CreateBuffer(SR ring weights) failed: {error}"
                ))
            })?;
    }
    let buffer =
        buffer.ok_or_else(|| PlayerError::Renderer("d3d11 SR ring buffer was null".to_string()))?;
    let resource: ID3D11Resource = buffer.cast().map_err(|error| {
        PlayerError::Renderer(format!("d3d11 SR ring buffer cast failed: {error}"))
    })?;
    let view_desc = D3D11_SHADER_RESOURCE_VIEW_DESC {
        Format: DXGI_FORMAT_R32G32B32A32_FLOAT,
        ViewDimension: D3D_SRV_DIMENSION_BUFFER,
        Anonymous: D3D11_SHADER_RESOURCE_VIEW_DESC_0 {
            Buffer: D3D11_BUFFER_SRV {
                Anonymous1: D3D11_BUFFER_SRV_0 { FirstElement: 0 },
                Anonymous2: D3D11_BUFFER_SRV_1 {
                    NumElements: weights.len().max(1) as u32,
                },
            },
        },
    };
    let mut view = None;
    unsafe {
        device
            .CreateShaderResourceView(&resource, Some(&view_desc), Some(&mut view))
            .map_err(|error| PlayerError::Renderer(format!("d3d11 SR ring SRV failed: {error}")))?;
    }
    view.ok_or_else(|| PlayerError::Renderer("d3d11 SR ring SRV was null".to_string()))
}

fn create_constants(device: &ID3D11Device, constants: &[[f32; 4]]) -> Result<ID3D11Buffer> {
    // Constant buffers bound with CSSetConstantBuffers1 must cover the
    // requested range; round up to whole 256-byte blocks.
    let mut padded = constants.to_vec();
    padded.resize(padded.len().max(1).div_ceil(16) * 16, [0.0; 4]);
    let desc = D3D11_BUFFER_DESC {
        ByteWidth: (padded.len() * 16) as u32,
        Usage: D3D11_USAGE_IMMUTABLE,
        BindFlags: D3D11_BIND_CONSTANT_BUFFER.0 as u32,
        CPUAccessFlags: 0,
        MiscFlags: 0,
        StructureByteStride: 0,
    };
    let data = D3D11_SUBRESOURCE_DATA {
        pSysMem: padded.as_ptr().cast::<c_void>(),
        SysMemPitch: 0,
        SysMemSlicePitch: 0,
    };
    let mut buffer = None;
    unsafe {
        device
            .CreateBuffer(&desc, Some(&data), Some(&mut buffer))
            .map_err(|error| {
                PlayerError::Renderer(format!("d3d11 CreateBuffer(SR weights) failed: {error}"))
            })?;
    }
    buffer.ok_or_else(|| PlayerError::Renderer("d3d11 SR weight buffer was null".to_string()))
}

fn create_params_buffer(
    device: &ID3D11Device,
    records: usize,
    offsetting: bool,
) -> Result<ID3D11Buffer> {
    let size = if offsetting {
        records.max(1) * PARAMS_STRIDE
    } else {
        mem::size_of::<DispatchParams>()
    };
    let desc = D3D11_BUFFER_DESC {
        ByteWidth: size as u32,
        Usage: D3D11_USAGE_DEFAULT,
        BindFlags: D3D11_BIND_CONSTANT_BUFFER.0 as u32,
        CPUAccessFlags: 0,
        MiscFlags: 0,
        StructureByteStride: 0,
    };
    let mut buffer = None;
    unsafe {
        device
            .CreateBuffer(&desc, None, Some(&mut buffer))
            .map_err(|error| {
                PlayerError::Renderer(format!("d3d11 CreateBuffer(SR params) failed: {error}"))
            })?;
    }
    buffer.ok_or_else(|| PlayerError::Renderer("d3d11 SR params buffer was null".to_string()))
}

/// `array_size == 0` creates a plain 2D texture (with 2D views).
fn create_texture(
    device: &ID3D11Device,
    width: u32,
    height: u32,
    array_size: u32,
    format: DXGI_FORMAT,
) -> Result<(
    ID3D11Texture2D,
    ID3D11ShaderResourceView,
    ID3D11UnorderedAccessView,
)> {
    let desc = D3D11_TEXTURE2D_DESC {
        Width: width.max(1),
        Height: height.max(1),
        MipLevels: 1,
        ArraySize: array_size.max(1),
        Format: format,
        SampleDesc: DXGI_SAMPLE_DESC {
            Count: 1,
            Quality: 0,
        },
        Usage: D3D11_USAGE_DEFAULT,
        BindFlags: D3D11_BIND_SHADER_RESOURCE.0 as u32 | D3D11_BIND_UNORDERED_ACCESS.0 as u32,
        CPUAccessFlags: 0,
        MiscFlags: 0,
    };
    let mut texture = None;
    unsafe {
        device
            .CreateTexture2D(&desc, None, Some(&mut texture))
            .map_err(|error| {
                PlayerError::Renderer(format!(
                    "d3d11 CreateTexture2D(SR {width}x{height}x{array_size}) failed: {error}"
                ))
            })?;
    }
    let texture =
        texture.ok_or_else(|| PlayerError::Renderer("d3d11 SR texture was null".to_string()))?;
    let resource: ID3D11Resource = texture
        .cast()
        .map_err(|error| PlayerError::Renderer(format!("d3d11 SR texture cast failed: {error}")))?;
    let mut srv = None;
    let mut uav = None;
    unsafe {
        // Default views: Texture2DArray for array textures created with
        // ArraySize > 1 needs explicit descs only when ArraySize == 1, where
        // the default view is Texture2D. Kernels declare Texture2DArray for
        // tensors, so request array views explicitly.
        if array_size > 0 {
            use ::windows::Win32::Graphics::Direct3D::D3D_SRV_DIMENSION_TEXTURE2DARRAY;
            use ::windows::Win32::Graphics::Direct3D11::{
                D3D11_SHADER_RESOURCE_VIEW_DESC, D3D11_SHADER_RESOURCE_VIEW_DESC_0,
                D3D11_TEX2D_ARRAY_SRV, D3D11_TEX2D_ARRAY_UAV, D3D11_UAV_DIMENSION_TEXTURE2DARRAY,
                D3D11_UNORDERED_ACCESS_VIEW_DESC, D3D11_UNORDERED_ACCESS_VIEW_DESC_0,
            };
            let srv_desc = D3D11_SHADER_RESOURCE_VIEW_DESC {
                Format: format,
                ViewDimension: D3D_SRV_DIMENSION_TEXTURE2DARRAY,
                Anonymous: D3D11_SHADER_RESOURCE_VIEW_DESC_0 {
                    Texture2DArray: D3D11_TEX2D_ARRAY_SRV {
                        MostDetailedMip: 0,
                        MipLevels: 1,
                        FirstArraySlice: 0,
                        ArraySize: array_size,
                    },
                },
            };
            let uav_desc = D3D11_UNORDERED_ACCESS_VIEW_DESC {
                Format: format,
                ViewDimension: D3D11_UAV_DIMENSION_TEXTURE2DARRAY,
                Anonymous: D3D11_UNORDERED_ACCESS_VIEW_DESC_0 {
                    Texture2DArray: D3D11_TEX2D_ARRAY_UAV {
                        MipSlice: 0,
                        FirstArraySlice: 0,
                        ArraySize: array_size,
                    },
                },
            };
            device
                .CreateShaderResourceView(&resource, Some(&srv_desc), Some(&mut srv))
                .map_err(|error| PlayerError::Renderer(format!("d3d11 SR SRV failed: {error}")))?;
            device
                .CreateUnorderedAccessView(&resource, Some(&uav_desc), Some(&mut uav))
                .map_err(|error| PlayerError::Renderer(format!("d3d11 SR UAV failed: {error}")))?;
        } else {
            device
                .CreateShaderResourceView(&resource, None, Some(&mut srv))
                .map_err(|error| PlayerError::Renderer(format!("d3d11 SR SRV failed: {error}")))?;
            device
                .CreateUnorderedAccessView(&resource, None, Some(&mut uav))
                .map_err(|error| PlayerError::Renderer(format!("d3d11 SR UAV failed: {error}")))?;
        }
    }
    Ok((
        texture,
        srv.ok_or_else(|| PlayerError::Renderer("d3d11 SR SRV was null".to_string()))?,
        uav.ok_or_else(|| PlayerError::Renderer("d3d11 SR UAV was null".to_string()))?,
    ))
}

fn constant_buffer_offsetting(device: &ID3D11Device) -> bool {
    if std::env::var_os("ERIKA_SR_NO_CB_OFFSET").is_some() {
        return false;
    }
    let mut options = D3D11_FEATURE_DATA_D3D11_OPTIONS::default();
    let supported = unsafe {
        device.CheckFeatureSupport(
            D3D11_FEATURE_D3D11_OPTIONS,
            (&mut options as *mut D3D11_FEATURE_DATA_D3D11_OPTIONS).cast::<c_void>(),
            mem::size_of::<D3D11_FEATURE_DATA_D3D11_OPTIONS>() as u32,
        )
    };
    supported.is_ok() && options.ConstantBufferOffsetting.as_bool()
}

fn create_query_ring(device: &ID3D11Device) -> Vec<QuerySet> {
    let make = |kind| -> Option<ID3D11Query> {
        let desc = D3D11_QUERY_DESC {
            Query: kind,
            MiscFlags: 0,
        };
        let mut query = None;
        unsafe { device.CreateQuery(&desc, Some(&mut query)) }.ok()?;
        query
    };
    (0..QUERY_RING)
        .filter_map(|_| {
            Some(QuerySet {
                disjoint: make(D3D11_QUERY_TIMESTAMP_DISJOINT)?,
                start: make(D3D11_QUERY_TIMESTAMP)?,
                end: make(D3D11_QUERY_TIMESTAMP)?,
                pending: false,
            })
        })
        .collect()
}

/// Waits for the profile queries and prints GPU time per kernel.
fn print_profile(
    context: &ID3D11DeviceContext,
    network: &Network,
    pool: &Pool,
    set: &QuerySet,
    records: &[DispatchRecord],
    stamps: &[(ID3D11Query, ID3D11Query)],
) {
    unsafe {
        context.End(&set.disjoint);
        context.Flush();
    }
    let disjoint = loop {
        if let Some(data) =
            read_query::<D3D11_QUERY_DATA_TIMESTAMP_DISJOINT>(context, &set.disjoint, |data| {
                data.Frequency != 0
            })
        {
            break data;
        }
        std::hint::spin_loop();
    };
    let wait = |query: &ID3D11Query| loop {
        if let Some(value) = read_query::<u64>(context, query, |value| *value != 0) {
            return value;
        }
        std::hint::spin_loop();
    };
    assert!(!disjoint.Disjoint.as_bool(), "disjoint profile timestamps");
    let start = wait(&set.start);
    let mut previous = start;
    let mut sum = 0.0;
    let mut gaps = 0.0;
    for (record, stamp) in records.iter().zip(stamps) {
        let begin = wait(&stamp.0);
        let now = wait(&stamp.1);
        let ms = (now.saturating_sub(begin)) as f64 / disjoint.Frequency as f64 * 1000.0;
        let gap = (begin.saturating_sub(previous)) as f64 / disjoint.Frequency as f64 * 1000.0;
        sum += ms;
        gaps += gap;
        previous = now;
        let spec = &network.plan.kernels[record.kernel];
        let layer = &network.model.layers[spec.layer];
        let label = format!(
            "L{} {}{}x{}->{} k{} [{}..{}]{}",
            spec.layer,
            if spec.head {
                "head "
            } else if spec.partial_head.is_some() {
                "head partial "
            } else {
                ""
            },
            layer
                .inputs
                .iter()
                .map(|input| input.kernel.to_string())
                .collect::<Vec<_>>()
                .join("+"),
            layer
                .inputs
                .iter()
                .map(|input| network.model.tensors[input.tensor])
                .sum::<usize>(),
            layer.out_channels,
            record.kernel,
            spec.out_start,
            spec.out_start + spec.out_count,
            if record.ring { " ring" } else { "" }
        );
        let pixels = if record.ring {
            let [x, y, w, h] = record.params.region;
            let [iw, ih, ..] = record.params.image;
            let rows = i32::from(y == 0) + i32::from(y + h == ih);
            let columns = i32::from(x == 0) + i32::from(x + w == iw);
            f64::from(rows * w + columns * (h - rows))
        } else {
            f64::from(record.params.region[2]) * f64::from(record.params.region[3])
        };
        let mut per_pixel_macs = spec.partial_head.as_ref().map_or_else(
            || {
                layer
                    .inputs
                    .iter()
                    .map(|input| {
                        network.model.tensors[input.tensor]
                            * input.kernel
                            * input.kernel
                            * spec.out_count
                    })
                    .sum::<usize>()
            },
            |part| part.macs,
        );
        if spec.dense.is_some() {
            let dense_head = network.model.layers.last().expect("dense head");
            per_pixel_macs += dense_head
                .inputs
                .iter()
                .filter(|input| input.tensor == layer.output)
                .map(|input| network.model.tensors[input.tensor] * 4)
                .sum::<usize>();
        }
        let macs = per_pixel_macs as f64 * pixels;
        // Logical texture traffic, including duplicated halo staging. This is
        // a requested-byte rate, not measured DRAM traffic (caches coalesce it).
        let reads = spec
            .sources
            .iter()
            .map(|source| {
                let bytes = if source.tensor == 0 {
                    1
                } else {
                    source.slices * 8
                };
                if source.radius == 0 || record.ring {
                    pixels
                        * bytes as f64
                        * if record.ring {
                            (2 * source.radius + 1).pow(2) as f64
                        } else {
                            1.0
                        }
                } else {
                    let block = spec.shape.block();
                    (block.0 as usize + 2 * source.radius) as f64
                        * (block.1 as usize + 2 * source.radius) as f64
                        * f64::from(record.groups.0)
                        * f64::from(record.groups.1)
                        * bytes as f64
                }
            })
            .sum::<f64>();
        let partial_texel_bytes = (pool.partial_bytes / 2) as f64;
        let previous_partial = spec.dense.as_ref().is_some_and(|dense| dense.step > 0)
            || spec.partial_head.as_ref().is_some_and(|part| part.step > 0);
        let mut reads = reads
            + if previous_partial {
                pixels * partial_texel_bytes
            } else {
                0.0
            };
        if layer.residual.is_some() {
            reads += pixels * spec.out_count.div_ceil(4) as f64 * 8.0;
        }
        if spec.head && network.model.head.base == crate::renderer::sr::model::HeadBase::Bilinear {
            reads += pixels * 9.0;
        }
        let mut writes = pixels
            * if spec.head {
                8.0
            } else if spec.partial_head.is_some() {
                0.0
            } else {
                spec.out_count.div_ceil(4) as f64 * 8.0
            };
        if spec.dense.as_ref().is_some_and(|dense| !dense.last)
            || spec.partial_head.as_ref().is_some_and(|part| !part.last)
        {
            writes += pixels * partial_texel_bytes;
        }
        eprintln!(
            "  {label:<48} {ms:8.4} ms gap {gap:.4} ms {:6.2} TF/s {:7.1} GB/s requested region {:?}",
            2.0 * macs / ms / 1e9,
            (reads + writes) / ms / 1e6,
            record.params.region
        );
    }
    let whole = (wait(&set.end) - start) as f64 / disjoint.Frequency as f64 * 1000.0;
    eprintln!(
        "SR profile {}: {} dispatches kernel_sum {sum:.4} ms gaps {gaps:.4} ms whole {whole:.4} ms",
        network.model.name,
        stamps.len()
    );
}

/// Non-blocking query read. windows-rs maps `S_FALSE` (not ready) to `Ok`,
/// so readiness is detected from a value that is never zero once written.
fn read_query<T: Default>(
    context: &ID3D11DeviceContext,
    query: &ID3D11Query,
    ready: impl Fn(&T) -> bool,
) -> Option<T> {
    use ::windows::Win32::Graphics::Direct3D11::D3D11_ASYNC_GETDATA_DONOTFLUSH;
    let asynchronous: ID3D11Asynchronous = query.cast().ok()?;
    let mut data = T::default();
    unsafe {
        context
            .GetData(
                &asynchronous,
                Some((&mut data as *mut T).cast::<c_void>()),
                mem::size_of::<T>() as u32,
                D3D11_ASYNC_GETDATA_DONOTFLUSH.0 as u32,
            )
            .ok()?;
    }
    ready(&data).then_some(data)
}

/// Compiles every distinct kernel source of `plan` on a few threads and
/// returns one blob per kernel.
fn compile_plan(plan: &D3d11Plan) -> std::result::Result<Vec<Vec<u8>>, String> {
    let mut unique: Vec<&str> = Vec::new();
    // Kernel sources first, then ring sources of the kernels that have one.
    let sources: Vec<&str> = plan
        .kernels
        .iter()
        .map(|kernel| kernel.source_code.as_str())
        .chain(
            plan.kernels
                .iter()
                .filter_map(|kernel| kernel.ring.as_ref().map(|ring| ring.source_code.as_str())),
        )
        .collect();
    let index: Vec<usize> = sources
        .iter()
        .map(
            |source| match unique.iter().position(|candidate| candidate == source) {
                Some(position) => position,
                None => {
                    unique.push(source);
                    unique.len() - 1
                }
            },
        )
        .collect();
    let threads = std::thread::available_parallelism()
        .map_or(2, |count| count.get())
        .clamp(1, 8)
        .min(unique.len().max(1));
    let next = std::sync::atomic::AtomicUsize::new(0);
    let results: Vec<std::sync::Mutex<Option<std::result::Result<Vec<u8>, String>>>> =
        unique.iter().map(|_| std::sync::Mutex::new(None)).collect();
    std::thread::scope(|scope| {
        for _ in 0..threads {
            scope.spawn(|| {
                loop {
                    let item = next.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                    let Some(source) = unique.get(item) else {
                        break;
                    };
                    *results[item].lock().expect("compile slot") = Some(compile_cached(source));
                }
            });
        }
    });
    let blobs = results
        .into_iter()
        .map(|slot| slot.into_inner().expect("compile slot").expect("compiled"))
        .collect::<std::result::Result<Vec<_>, _>>()?;
    Ok(index.into_iter().map(|item| blobs[item].clone()).collect())
}

/// Compiles `source` with FXC, using an on-disk cache keyed by the source.
fn compile_cached(source: &str) -> std::result::Result<Vec<u8>, String> {
    let flags = std::env::var("ERIKA_SR_FXC").unwrap_or_default();
    let key = fnv1a(
        format!("{SHADER_CACHE_VERSION}/{flags}").as_bytes(),
        source.as_bytes(),
    );
    let path = cache_dir().map(|dir| dir.join(format!("{key:016x}.dxbc")));
    if let Some(path) = path.as_ref() {
        if let Ok(bytes) = std::fs::read(path) {
            if !bytes.is_empty() {
                return Ok(bytes);
            }
        }
    }
    let blob = compile(source)?;
    if let Some(path) = path {
        if let Some(parent) = path.parent() {
            let _ = std::fs::create_dir_all(parent);
        }
        let temporary = path.with_extension(format!("tmp{}", std::process::id()));
        if std::fs::write(&temporary, &blob).is_ok() {
            let _ = std::fs::rename(&temporary, &path);
        }
    }
    Ok(blob)
}

fn cache_dir() -> Option<PathBuf> {
    if std::env::var_os("ERIKA_SR_NO_SHADER_CACHE").is_some() {
        return None;
    }
    if let Some(directory) = std::env::var_os("ERIKA_SR_SHADER_CACHE_DIR") {
        return Some(PathBuf::from(directory));
    }
    std::env::var_os("LOCALAPPDATA")
        .map(PathBuf::from)
        .map(|dir| dir.join("liberika").join("sr-shader-cache"))
}

fn fnv1a(salt: &[u8], data: &[u8]) -> u64 {
    let mut hash = 0xcbf2_9ce4_8422_2325u64;
    for &byte in salt.iter().chain(data) {
        hash ^= u64::from(byte);
        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
    }
    hash
}

pub(crate) fn compile(source: &str) -> std::result::Result<Vec<u8>, String> {
    use ::windows::Win32::Graphics::Direct3D::Fxc::{
        D3DCOMPILE_OPTIMIZATION_LEVEL1, D3DCOMPILE_SKIP_OPTIMIZATION,
    };
    let flags = match std::env::var("ERIKA_SR_FXC").as_deref() {
        Ok("skip") => D3DCOMPILE_SKIP_OPTIMIZATION,
        Ok("o3") => D3DCOMPILE_OPTIMIZATION_LEVEL3,
        _ => D3DCOMPILE_OPTIMIZATION_LEVEL1,
    };
    compile_with_flags(source, flags)
}

pub(crate) fn compile_with_flags(source: &str, flags: u32) -> std::result::Result<Vec<u8>, String> {
    let entry = b"main\0";
    let target = b"cs_5_0\0";
    let mut code: Option<ID3DBlob> = None;
    let mut errors: Option<ID3DBlob> = None;
    let result = unsafe {
        D3DCompile(
            source.as_ptr().cast::<c_void>(),
            source.len(),
            PCSTR::null(),
            None,
            None,
            PCSTR(entry.as_ptr()),
            PCSTR(target.as_ptr()),
            flags,
            0,
            &mut code,
            Some(&mut errors),
        )
    };
    if let Err(error) = result {
        let message = errors
            .as_ref()
            .map(|blob| {
                String::from_utf8_lossy(blob_bytes(blob))
                    .trim_end_matches('\0')
                    .to_string()
            })
            .unwrap_or_else(|| error.message());
        return Err(format!("D3DCompile(SR kernel) failed: {message}"));
    }
    code.map(|blob| blob_bytes(&blob).to_vec())
        .ok_or_else(|| "D3DCompile returned no code".to_string())
}

fn blob_bytes(blob: &ID3DBlob) -> &[u8] {
    unsafe {
        std::slice::from_raw_parts(blob.GetBufferPointer().cast::<u8>(), blob.GetBufferSize())
    }
}

/// AMD FSR 1.0 (EASU + RCAS, fused) on luma, scaling straight to the
/// presentation size.
#[derive(Default)]
pub(crate) struct D3d11Fsr1 {
    shader: Option<ID3D11ComputeShader>,
    pending: Option<Receiver<std::result::Result<Vec<u8>, String>>>,
    params: Option<ID3D11Buffer>,
    output: Option<(
        (u32, u32, u32, u32),
        (
            ID3D11Texture2D,
            ID3D11ShaderResourceView,
            ID3D11UnorderedAccessView,
        ),
    )>,
    frame_cache: FrameTokenCache,
    failure: Option<String>,
    frames: u64,
    sampler: Option<::windows::Win32::Graphics::Direct3D11::ID3D11SamplerState>,
    tile: u32,
    pixels: (u32, u32),
}

#[repr(C)]
#[derive(Clone, Copy, Default)]
struct FsrParams {
    scale: [f32; 4],
    sizes: [i32; 4],
    sharp: [f32; 4],
}

impl D3d11Fsr1 {
    pub(crate) fn status(&self) -> LumaUpscalerBackendStatus {
        if self.failure.is_some() {
            LumaUpscalerBackendStatus::Inactive
        } else if self.shader.is_some() {
            LumaUpscalerBackendStatus::Scalar
        } else {
            LumaUpscalerBackendStatus::Building
        }
    }

    pub(crate) fn frames(&self) -> u64 {
        self.frames
    }

    pub(crate) fn allocated_bytes(&self) -> u64 {
        self.output
            .as_ref()
            .map_or(0, |((_, _, width, height), _)| {
                u64::from(*width) * u64::from(*height) * 2
            })
    }

    pub(crate) fn last_failure(&self) -> Option<&str> {
        self.failure.as_deref()
    }

    /// Drops device resources (the compiled blob is recompiled from cache).
    pub(crate) fn reset(&mut self) {
        *self = Self::default();
    }

    /// Shader shape and source; kept separate for cold compile measurements.
    fn shader_source() -> (String, u32, (u32, u32)) {
        let tile = std::env::var("ERIKA_FSR_TILE")
            .ok()
            .and_then(|v| v.parse::<u32>().ok())
            .filter(|v| [8, 16, 32].contains(v))
            .unwrap_or(16);
        let knob = |name| {
            std::env::var(name)
                .ok()
                .and_then(|v| v.parse::<u32>().ok())
                .filter(|v| [1, 2, 4, 8].contains(v))
                .unwrap_or(4)
        };
        let (mut px, mut py) = (knob("ERIKA_FSR_PX"), knob("ERIKA_FSR_PY"));
        while (tile * px + 2) * (tile * py + 2) * 4 > 32 * 1024 {
            if px >= py {
                px = (px / 2).max(1);
            } else {
                py = (py / 2).max(1);
            }
        }
        let gather = std::env::var("ERIKA_FSR_GATHER").ok().as_deref() != Some("0");
        let fast_rcp = std::env::var("ERIKA_FSR_FAST_RCP").ok().as_deref() != Some("0");
        let source = format!(
            "#define TILE {tile}\n#define PX {px}\n#define PY {py}\n#define FSR_GATHER {}\n#define FSR_FAST_RCP {}\n{}",
            u8::from(gather),
            u8::from(fast_rcp),
            crate::renderer::sr::fsr1::HLSL
        );
        (source, tile, (px, py))
    }

    /// Starts the background compile once.
    pub(crate) fn prepare(&mut self) {
        if self.shader.is_some() || self.pending.is_some() || self.failure.is_some() {
            return;
        }
        let (source, tile, pixels) = Self::shader_source();
        self.tile = tile;
        self.pixels = pixels;
        let (sender, receiver) = channel();
        let spawned = std::thread::Builder::new()
            .name("erika-fsr1-compile".to_string())
            .spawn(move || {
                let _ = sender.send(compile_cached(&source));
            });
        match spawned {
            Ok(_) => self.pending = Some(receiver),
            Err(error) => self.failure = Some(format!("cannot spawn FSR1 compile thread: {error}")),
        }
    }

    /// Starts or finishes the background compile. Cheap when idle.
    pub(crate) fn poll(&mut self, device: &ID3D11Device) {
        self.prepare();
        let Some(receiver) = self.pending.as_ref() else {
            return;
        };
        let blob = match receiver.try_recv() {
            Ok(blob) => blob,
            Err(TryRecvError::Empty) => return,
            Err(TryRecvError::Disconnected) => Err("FSR1 compile thread exited".to_string()),
        };
        self.pending = None;
        let created = blob.and_then(|blob| {
            let mut shader = None;
            unsafe { device.CreateComputeShader(&blob, None, Some(&mut shader)) }
                .map_err(|error| format!("d3d11 CreateComputeShader(FSR1) failed: {error}"))?;
            shader.ok_or_else(|| "d3d11 CreateComputeShader(FSR1) returned null".to_string())
        });
        match created {
            Ok(shader) => self.shader = Some(shader),
            Err(error) => self.failure = Some(error),
        }
    }

    /// Scales `luma` (`width x height`) to `target` and sharpens it.
    pub(crate) fn encode(
        &mut self,
        device: &ID3D11Device,
        context: &ID3D11DeviceContext,
        luma: &ID3D11ShaderResourceView,
        source: (u32, u32),
        target: (u32, u32),
        frame_token: Option<u64>,
    ) -> Result<Option<UpscaledLuma>> {
        self.poll(device);
        let Some(shader) = self.shader.clone() else {
            return Ok(None);
        };
        let key = (source.0, source.1, target.0, target.1);
        if self
            .output
            .as_ref()
            .is_some_and(|(cached, _)| *cached == key)
            && self.frame_cache.matches(frame_token)
        {
            let (_, (_, view, _)) = self.output.as_ref().expect("checked");
            return Ok(Some(UpscaledLuma {
                view: view.clone(),
                width: target.0,
                height: target.1,
            }));
        }
        if self
            .output
            .as_ref()
            .is_none_or(|(cached, _)| *cached != key)
        {
            self.output = Some((
                key,
                create_texture(device, target.0, target.1, 0, DXGI_FORMAT_R16_FLOAT)?,
            ));
            self.frame_cache.invalidate();
        }
        if self.params.is_none() {
            self.params = Some(create_params_buffer(device, 1, false)?);
        }
        if self.sampler.is_none() {
            use ::windows::Win32::Graphics::Direct3D11::{
                D3D11_FILTER_MIN_MAG_MIP_POINT, D3D11_SAMPLER_DESC, D3D11_TEXTURE_ADDRESS_CLAMP,
            };
            let desc = D3D11_SAMPLER_DESC {
                Filter: D3D11_FILTER_MIN_MAG_MIP_POINT,
                AddressU: D3D11_TEXTURE_ADDRESS_CLAMP,
                AddressV: D3D11_TEXTURE_ADDRESS_CLAMP,
                AddressW: D3D11_TEXTURE_ADDRESS_CLAMP,
                MaxLOD: f32::MAX,
                ..Default::default()
            };
            unsafe { device.CreateSamplerState(&desc, Some(&mut self.sampler)) }
                .map_err(|e| PlayerError::Renderer(format!("FSR sampler: {e}")))?;
        }
        let ratio = (
            source.0 as f32 / target.0 as f32,
            source.1 as f32 / target.1 as f32,
        );
        let params = FsrParams {
            scale: [ratio.0, ratio.1, 0.5 * ratio.0 - 0.5, 0.5 * ratio.1 - 0.5],
            sizes: [
                source.0 as i32,
                source.1 as i32,
                target.0 as i32,
                target.1 as i32,
            ],
            sharp: [
                crate::renderer::sr::fsr1::rcas_strength(
                    crate::renderer::sr::fsr1::DEFAULT_SHARPNESS_STOPS,
                ),
                1.0 / source.0 as f32,
                1.0 / source.1 as f32,
                0.0,
            ],
        };
        let params_buffer = self.params.clone().expect("created above");
        let (_, (_, view, uav)) = self.output.as_ref().expect("created above");
        unsafe {
            context.UpdateSubresource(
                &params_buffer,
                0,
                None,
                (&params as *const FsrParams).cast::<c_void>(),
                0,
                0,
            );
            context.CSSetShader(&shader, None);
            context.CSSetConstantBuffers(0, Some(&[Some(params_buffer)]));
            context.CSSetShaderResources(0, Some(&[Some(luma.clone())]));
            context.CSSetSamplers(0, Some(&[self.sampler.clone()]));
            context.CSSetUnorderedAccessViews(0, 1, Some([Some(uav.clone())].as_ptr()), None);
            context.Dispatch(
                target.0.div_ceil(self.tile * self.pixels.0),
                target.1.div_ceil(self.tile * self.pixels.1),
                1,
            );
            context.CSSetUnorderedAccessViews(0, 1, Some([None].as_ptr()), None);
            context.CSSetShaderResources(0, Some(&[None]));
            context.CSSetSamplers(0, Some(&[None]));
            context.CSSetConstantBuffers(0, Some(&[None]));
            context.CSSetShader(None, None);
        }
        let view = view.clone();
        self.frame_cache.commit(frame_token);
        self.frames = self.frames.saturating_add(1);
        Ok(Some(UpscaledLuma {
            view,
            width: target.0,
            height: target.1,
        }))
    }
}

